var F = "12px ui-sans-serif, system-ui, sans-serif";
ctx.font = F;
ctx.lineWidth = 1;

var th = p.theta * Math.PI / 180;
var wallX = W * 0.22;
var midY = H * 0.5;
var gap = Math.min(H * 0.30, 90);
var yA = midY - gap / 2;
var yB = midY + gap / 2;

// wall
ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.moveTo(wallX, 6); ctx.lineTo(wallX, yA - 7);
ctx.moveTo(wallX, yA + 7); ctx.lineTo(wallX, yB - 7);
ctx.moveTo(wallX, yB + 7); ctx.lineTo(wallX, H - 6);
ctx.stroke();

// incoming plane wave fronts, animated
ctx.strokeStyle = C.faint;
for (var k = 0; k < 5; k++) {
  var xw = 8 + ((k * 14 + (t * 18) % 14) % (wallX - 12));
  ctx.beginPath(); ctx.moveTo(xw, 10); ctx.lineTo(xw, H - 10); ctx.stroke();
}

// two outgoing parallel rays at angle th
var len = W - wallX - 30;
var dx = Math.cos(th) * len, dy = -Math.sin(th) * len;
ctx.strokeStyle = C.accent;
ctx.lineWidth = 1.6;
ctx.beginPath(); ctx.moveTo(wallX, yA); ctx.lineTo(wallX + dx, yA + dy); ctx.stroke();
ctx.beginPath(); ctx.moveTo(wallX, yB); ctx.lineTo(wallX + dx, yB + dy); ctx.stroke();
ctx.lineWidth = 1;

// perpendicular dropped from upper slit onto lower ray
var d = gap;
var extra = d * Math.sin(th);            // path difference in pixels
var fx = wallX + extra * Math.cos(th);
var fy = yB - extra * Math.sin(th);
ctx.strokeStyle = C.figure;
ctx.setLineDash([3, 3]);
ctx.beginPath(); ctx.moveTo(wallX, yA); ctx.lineTo(fx, fy); ctx.stroke();
ctx.setLineDash([]);

// shade the little triangle
ctx.fillStyle = C.figure;
ctx.globalAlpha = 0.18;
ctx.beginPath();
ctx.moveTo(wallX, yA); ctx.lineTo(wallX, yB); ctx.lineTo(fx, fy); ctx.closePath();
ctx.fill();
ctx.globalAlpha = 1;

// the path-difference leg, bold
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2.5;
ctx.beginPath(); ctx.moveTo(wallX, yB); ctx.lineTo(fx, fy); ctx.stroke();
ctx.lineWidth = 1;

// slit dots
ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(wallX, yA, 3, 0, 6.2832); ctx.fill();
ctx.beginPath(); ctx.arc(wallX, yB, 3, 0, 6.2832); ctx.fill();

// separation bracket
ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.moveTo(wallX - 16, yA); ctx.lineTo(wallX - 16, yB);
ctx.moveTo(wallX - 20, yA); ctx.lineTo(wallX - 12, yA);
ctx.moveTo(wallX - 20, yB); ctx.lineTo(wallX - 12, yB);
ctx.stroke();

ctx.fillStyle = C.ink;
ctx.textAlign = "right";
ctx.fillText("d", wallX - 24, midY + 4);
ctx.textAlign = "left";
ctx.fillText("to screen, angle " + p.theta.toFixed(0) + " deg", wallX + dx * 0.55 + 6, yA + dy * 0.55 - 8);
ctx.fillStyle = C.accent;
ctx.fillText("path difference d sin(theta)", fx + 6, fy + 16);
ctx.fillStyle = C.faint;
ctx.fillText("incoming wave", 8, H - 14);

// readout: how many wavelengths
var dNM = p.d * 1000;                     // slit separation in nm (p.d in microns)
var pd = dNM * Math.sin(th);              // nm
out.note = "d = " + p.d.toFixed(2) + " um, theta = " + p.theta.toFixed(1)
  + " deg, path difference = " + pd.toFixed(0) + " nm = "
  + (pd / p.lam).toFixed(2) + " wavelengths"
  + (Math.abs(pd / p.lam - Math.round(pd / p.lam)) < 0.02 && pd > 1
     ? "  (bright, m = " + Math.round(pd / p.lam) + ")" : "");

var F = "12px ui-sans-serif, system-ui, sans-serif";
ctx.font = F;
var lam = p.lam * 1e-9;
var a = p.a * 1e-6;
var d = p.d * 1e-6;
if (d < a) d = a;

var pad = 30;
var x0 = pad, x1 = W - pad;
var yBase = H - 26, yTop = 18;
var sMax = 0.35;                     // sin(theta) at the edges of the plot

function Xs(s) { return (x0 + x1) / 2 + (s / sMax) * (x1 - x0) / 2; }
function Yi(I) { return yBase - I * (yBase - yTop); }

// axis
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(x0, yBase); ctx.lineTo(x1, yBase); ctx.stroke();
ctx.fillStyle = C.faint;
ctx.textAlign = "center";
ctx.fillText("sin(theta)  ->", (x0 + x1) / 2, H - 8);
ctx.fillText("-" + sMax.toFixed(2), x0, H - 8);
ctx.fillText("+" + sMax.toFixed(2), x1, H - 8);
ctx.textAlign = "left";
ctx.fillText("intensity", x0 + 2, yTop - 4);

// envelope (dashed)
ctx.strokeStyle = C.figure;
ctx.setLineDash([4, 4]);
ctx.beginPath();
var n, s, al, envv, fr, I;
for (n = 0; n <= 600; n++) {
  s = -sMax + 2 * sMax * n / 600;
  al = Math.PI * a * s / lam;
  envv = (Math.abs(al) < 1e-6) ? 1 : Math.pow(Math.sin(al) / al, 2);
  if (n === 0) ctx.moveTo(Xs(s), Yi(envv)); else ctx.lineTo(Xs(s), Yi(envv));
}
ctx.stroke();
ctx.setLineDash([]);

// full pattern (solid)
ctx.strokeStyle = C.accent;
ctx.lineWidth = 1.6;
ctx.beginPath();
for (n = 0; n <= 2000; n++) {
  s = -sMax + 2 * sMax * n / 2000;
  al = Math.PI * a * s / lam;
  envv = (Math.abs(al) < 1e-6) ? 1 : Math.pow(Math.sin(al) / al, 2);
  fr = Math.pow(Math.cos(Math.PI * d * s / lam), 2);
  I = envv * fr;
  if (n === 0) ctx.moveTo(Xs(s), Yi(I)); else ctx.lineTo(Xs(s), Yi(I));
}
ctx.stroke();
ctx.lineWidth = 1;

// mark envelope zeros
ctx.strokeStyle = C.faint;
ctx.setLineDash([2, 4]);
for (var k = 1; k <= 6; k++) {
  var sz = k * lam / a;
  if (sz > sMax) break;
  ctx.beginPath(); ctx.moveTo(Xs(sz), yTop); ctx.lineTo(Xs(sz), yBase); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(Xs(-sz), yTop); ctx.lineTo(Xs(-sz), yBase); ctx.stroke();
}
ctx.setLineDash([]);

ctx.fillStyle = C.figure;
ctx.fillText("envelope from slit width a", x0 + 2, yTop + 12);

// count fringes strictly inside central envelope
var ratio = d / a;
var mMax = Math.ceil(ratio) - 1;
if (Math.abs(ratio - Math.round(ratio)) < 1e-6) mMax = Math.round(ratio) - 1;
var count = 2 * mMax + 1;
var missing = (Math.abs(ratio - Math.round(ratio)) < 1e-6)
  ? "  orders " + Math.round(ratio) + ", " + (2 * Math.round(ratio)) + ", ... missing"
  : "  no missing orders";
out.note = "d/a = " + ratio.toFixed(2) + ",  " + count
  + " maxima inside the central envelope," + missing;

var F = "12px ui-sans-serif, system-ui, sans-serif";
ctx.font = F;
var lam = p.lam * 1e-9;
var d = p.d * 1e-6;
var N = Math.round(p.N);

var pad = 30;
var x0 = pad, x1 = W - pad;
var yBase = H - 26, yTop = 18;
var sMax = 0.8;

function Xs(s) { return (x0 + x1) / 2 + (s / sMax) * (x1 - x0) / 2; }
function Yi(I) { return yBase - I * (yBase - yTop); }

ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(x0, yBase); ctx.lineTo(x1, yBase); ctx.stroke();
ctx.fillStyle = C.faint;
ctx.textAlign = "center";
ctx.fillText("sin(theta)  ->", (x0 + x1) / 2, H - 8);
ctx.textAlign = "left";
ctx.fillText("intensity / N^2", x0 + 2, yTop - 4);

// N-slit interference function, normalised to 1 at a principal maximum
ctx.strokeStyle = C.accent;
ctx.lineWidth = 1.6;
ctx.beginPath();
var n, s, ph, num, den, I;
for (n = 0; n <= 3000; n++) {
  s = -sMax + 2 * sMax * n / 3000;
  ph = Math.PI * d * s / lam;
  den = Math.sin(ph);
  if (Math.abs(den) < 1e-9) { I = 1; }
  else { num = Math.sin(N * ph); I = Math.pow(num / (N * den), 2); }
  if (I > 1) I = 1;
  if (n === 0) ctx.moveTo(Xs(s), Yi(I)); else ctx.lineTo(Xs(s), Yi(I));
}
ctx.stroke();
ctx.lineWidth = 1;

// label the orders
ctx.fillStyle = C.figure;
ctx.textAlign = "center";
for (var m = -6; m <= 6; m++) {
  var sm = m * lam / d;
  if (Math.abs(sm) > sMax) continue;
  ctx.fillText("m=" + m, Xs(sm), yTop + 10);
}
ctx.textAlign = "left";

var s1 = lam / d;
var ang = (Math.abs(s1) <= 1) ? (Math.asin(s1) * 180 / Math.PI).toFixed(1) + " deg" : "none";
var mMaxOrder = Math.floor(d / lam);
out.note = "N = " + N + " slits, d = " + p.d.toFixed(2) + " um: first order at "
  + ang + ", highest order m = " + mMaxOrder
  + ", resolving power in first order = " + N;
